import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageTeachers() {
  const [teachers, setTeachers] = useState([]);
  const [subjects, setSubjects] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editId, setEditId] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');
  
  const [formData, setFormData] = useState({ name: '', username: '', subject: '', qualifications: '', email: '', phone_number: '', address: '', password: 'TC@123' });

  const fetchTeachers = () => axios.get('http://localhost:8081/api/view-teachers').then(res => setTeachers(res.data));
  const fetchSubjects = () => axios.get('http://localhost:8081/api/view-subjects').then(res => setSubjects(res.data));

  useEffect(() => { fetchTeachers(); fetchSubjects(); }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    const apiPath = isEditing ? `http://localhost:8081/api/edit-teacher/${editId}` : 'http://localhost:8081/api/add-teacher';
    const method = isEditing ? axios.put : axios.post;

    method(apiPath, formData).then((res) => { 
        if(res.data.status === "Error") alert("Error: " + res.data.error); 
        else { fetchTeachers(); resetForm(); }
    }).catch(() => alert("Server Error!"));
  };

  const handleEdit = (t) => {
    setIsEditing(true); setEditId(t.id);
    setFormData({ name: t.name, subject: t.Subject || '', qualifications: t.qualifications || '', email: t.email || '', phone_number: t.phone_number, address: t.address || '' });
    setShowForm(true);
  };

  const handleDelete = (id) => {
    if (window.confirm("Are you sure you want to delete this teacher?")) {
      axios.delete(`http://localhost:8081/api/delete-teacher/${id}`).then(() => fetchTeachers());
    }
  };

  const resetForm = () => { setShowForm(false); setIsEditing(false); setEditId(null); setFormData({ name: '', username: '', subject: '', qualifications: '', email: '', phone_number: '', address: '', password: 'TC@123' }); };

  const filteredTeachers = teachers.filter(t => (t.name || '').toLowerCase().includes(searchQuery.toLowerCase()));

  return (
    <div style={{ padding: '30px', fontFamily: 'sans-serif', backgroundColor: '#f8fafc', minHeight: '100vh' }}>
      <div style={{ backgroundColor: '#fff', padding: '20px', borderRadius: '12px', boxShadow: '0 2px 10px rgba(0,0,0,0.05)', marginBottom: '20px' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <h2 style={{ margin: 0, color: '#1e293b', fontSize: '20px', display: 'flex', alignItems: 'center', gap: '10px' }}>🧑‍🏫 Manage Teachers</h2>
          <div style={{ display: 'flex', gap: '15px' }}>
            <input type="text" placeholder="Search Teacher..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} style={styles.searchInput} />
            <button onClick={() => {resetForm(); setShowForm(true);}} style={styles.primaryBtn}>+ Add New Teacher</button>
          </div>
        </div>

        <table style={{ width: '100%', marginTop: '20px', borderCollapse: 'collapse', textAlign: 'left' }}>
          <thead>
            <tr style={{ borderBottom: '2px solid #e2e8f0' }}>
              <th style={styles.th}>No.</th>
              <th style={styles.th}>Full Name</th>
              <th style={styles.th}>Teaching Subject</th>
              <th style={styles.th}>Qualifications</th>
              <th style={styles.th}>Phone Number</th>
              <th style={styles.th}>Email</th>
              <th style={styles.th}>Address</th>
              <th style={styles.th}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {/* 🟢 ID එක අනුව බලෙන්ම අලුත්ම ගුරුවරයාව වගුවේ ඉහළටම Sort කිරීම */}
            {[...filteredTeachers].sort((a, b) => b.id - a.id).map((t, index) => (
              <tr key={t.id} style={{ borderBottom: '1px solid #f1f5f9' }}>
<td style={styles.td}>{filteredTeachers.length - index}</td>
                <td style={{...styles.td, fontWeight: 'bold', color: '#15803d'}}>{t.name}</td>
                <td style={{...styles.td, color: '#0369a1', fontSize: '13px'}}>{t.Subject || '-'}</td>
                <td style={{...styles.td, color: '#64748b', fontSize: '13px'}}>{t.qualifications || '-'}</td>
                <td style={styles.td}>{t.phone_number}</td>
                <td style={{...styles.td, color: '#475569', fontSize: '13px'}}>{t.email || 'No Email'}</td>
                <td style={{...styles.td, color: '#475569'}}>{t.address || 'No Address'}</td>
                <td style={styles.td}>
                  <button onClick={() => handleEdit(t)} style={styles.iconBtn}>✏️</button>
                  <button onClick={() => handleDelete(t.id)} style={styles.iconBtn}>🗑️</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {showForm && (
        <div style={styles.modalOverlay}>
          <div style={styles.modal}>
            <h3 style={{ margin: '0 0 20px 0', color: '#1e293b' }}>{isEditing ? '✏️ Edit Teacher' : '➕ Add New Teacher'}</h3>
            <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
              <input type="text" placeholder="Teacher Full Name" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} required style={styles.input} />
              {!isEditing && (
                <div style={{ display: 'flex', gap: '10px' }}>
                  <input type="text" placeholder="Login Username" value={formData.username} onChange={e => setFormData({...formData, username: e.target.value})} required style={styles.input} />
                  <input type="text" placeholder="Password" value={formData.password} onChange={e => setFormData({...formData, password: e.target.value})} required style={styles.input} />
                </div>
              )}
              <select value={formData.subject} onChange={e => setFormData({...formData, subject: e.target.value})} style={styles.input} required>
                <option value="">-- Select Teaching Subject --</option>
                {subjects.map(s => <option key={s.id} value={s.subject_name}>{s.subject_name}</option>)}
              </select>
              <input type="text" placeholder="Qualifications" value={formData.qualifications} onChange={e => setFormData({...formData, qualifications: e.target.value})} style={styles.input} />
              <div style={{ display: 'flex', gap: '10px' }}>
                <input type="text" placeholder="Phone" value={formData.phone_number} onChange={e => setFormData({...formData, phone_number: e.target.value})} required style={styles.input} />
                <input type="email" placeholder="Email" value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} style={styles.input} />
              </div>
              <input type="text" placeholder="Address" value={formData.address} onChange={e => setFormData({...formData, address: e.target.value})} style={styles.input} />
              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '10px', marginTop: '10px' }}>
                <button type="button" onClick={resetForm} style={styles.cancelBtn}>Cancel</button>
                <button type="submit" style={styles.saveBtn}>{isEditing ? 'Update Details' : 'Save Teacher'}</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

const styles = {
  searchInput: { padding: '8px 15px', borderRadius: '20px', border: '1px solid #cbd5e1', outline: 'none', width: '220px', fontSize: '13px', backgroundColor: '#f8fafc' },
  primaryBtn: { padding: '8px 15px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px' },
  th: { padding: '12px 10px', color: '#64748b', fontWeight: 'bold', fontSize: '13px' },
  td: { padding: '15px 10px', fontSize: '14px', verticalAlign: 'top' },
  iconBtn: { background: 'none', border: 'none', cursor: 'pointer', fontSize: '16px', marginRight: '10px' },
  modalOverlay: { position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', backgroundColor: 'rgba(0,0,0,0.5)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000 },
  modal: { backgroundColor: 'white', padding: '30px', borderRadius: '15px', width: '500px', boxShadow: '0 20px 25px -5px rgba(0,0,0,0.1)' },
  input: { padding: '10px 15px', borderRadius: '8px', border: '1px solid #cbd5e1', width: '100%', boxSizing: 'border-box', outline: 'none', fontSize: '13px', backgroundColor: '#f8fafc' },
  cancelBtn: { padding: '10px 20px', background: 'none', color: '#64748b', border: 'none', cursor: 'pointer', fontWeight: 'bold', fontSize: '14px' },
  saveBtn: { padding: '10px 20px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '14px' }
};
